\begin{tikzpicture}[scale=0.95]
  % Axes
  \draw[->, thick, draw=gray!70] (-1.0, 0) -- (6.5, 0) node[right, font=\small] {$x$};
  \draw[->, thick, draw=gray!70] (0, -0.8) -- (0, 4.2) node[above, font=\small] {$f(x)$};

  % Smooth function curve with local and global minima
  \draw[thick, draw=blue!70!black, domain=-0.5:6.0, samples=100] 
    plot (\x, {0.12*(\x-1.0)*(\x-2.8)*(\x-4.8)*(\x-5.5) + 1.2});

  % Global minimum at x* ~ 1.7
  \coordinate (Xstar) at (1.75, 0.45);
  \fill[orange!85!black] (Xstar) circle (2.5pt);
  \draw[dashed, draw=orange!85!black] (1.75, 0) -- (Xstar);
  \node[below, font=\footnotesize, text=orange!85!black] at (1.75, 0) {$x^*$ (Global Min)};

  % Local minimum at xbar ~ 4.2
  \coordinate (Xbar) at (4.25, 1.35);
  \fill[blue!70!black] (Xbar) circle (2.5pt);
  \draw[dashed, draw=blue!70!black] (4.25, 0) -- (Xbar);
  \node[below, font=\footnotesize, text=blue!70!black] at (4.25, 0) {$\bar{x}$ (Local Min)};

  % Delta neighborhood (xbar - delta, xbar + delta)
  \draw[|<->|, thick, draw=teal] (3.4, 0.2) -- (5.1, 0.2) 
    node[midway, above, font=\scriptsize, text=teal] {$(\bar{x}-\delta, \, \bar{x}+\delta)$};
  \draw[dotted, draw=teal] (3.4, 0) -- (3.4, 1.8);
  \draw[dotted, draw=teal] (5.1, 0) -- (5.1, 1.8);

  % Function label
  \node[text=blue!70!black, font=\small\bfseries] at (5.8, 3.8) {$f(x)$};
