\begin{tikzpicture}[scale=0.95]
  % Axes
  \draw[->, thick, draw=gray!70] (-0.5, 0) -- (6.0, 0) node[right, font=\small] {$x$};
  \draw[->, thick, draw=gray!70] (0, -0.5) -- (0, 4.5) node[above, font=\small] {$f(x)$};

  % Convex curve f(x) = 0.2*(x-2)^2 + 0.6
  \draw[thick, draw=blue!70!black, domain=0.5:5.5, samples=80] 
    plot (\x, {0.25*(\x-1.5)*(\x-1.5) + 0.8});
  \node[text=blue!70!black, font=\small\bfseries] at (5.5, 4.2) {$f(x)$};

  % Point x
  \coordinate (Px) at (1.2, 0.82);
  \fill[orange!85!black] (Px) circle (2pt);
  \draw[dashed, draw=gray] (1.2, 0) -- (Px);
  \node[below, font=\footnotesize] at (1.2, 0) {$x$};

  % Point y
  \coordinate (Py) at (4.8, 3.52);
  \fill[orange!85!black] (Py) circle (2pt);
  \draw[dashed, draw=gray] (4.8, 0) -- (Py);
  \node[below, font=\footnotesize] at (4.8, 0) {$y$};

  % Secant chord line between (x, f(x)) and (y, f(y))
  \draw[thick, draw=orange!85!black] (Px) -- (Py) 
    node[midway, above left, font=\scriptsize, text=orange!85!black, rotate=38] {Secant Chord $\theta f(x) + (1-\theta)f(y)$};

  % Intermediate point theta*x + (1-theta)*y
  \coordinate (Pmid_x) at (3.0, 0);
  \coordinate (Pmid_curve) at (3.0, 1.36);
  \coordinate (Pmid_chord) at (3.0, 2.17);

  \draw[dashed, draw=teal] (3.0, 0) -- (Pmid_chord);
  \fill[teal] (Pmid_curve) circle (2pt);
  \fill[orange!85!black] (Pmid_chord) circle (2pt);
  \node[below, font=\scriptsize] at (3.0, 0) {$\theta x + (1-\theta)y$};
  \node[right, font=\tiny, text=blue!70!black] at (Pmid_curve) {$f(\theta x + (1-\theta)y)$};
\end{tikzpicture}

