\begin{tikzpicture}[
    >=LaTeX, % Use default LaTeX arrows
    thick,
    x=2cm,
    node distance=1.75em,
    % Styles 
    cell/.style={
        rectangle,
        fill=white!10,
        rounded corners=2mm,
        minimum height=2em,
        minimum width=2.5em,
        draw,
        thick
    },
    arrow/.style={
        -latex,
        very thick
    }
]

    \node foreach[count=\i] \t in {$\mathbf{Q}$, $\mathbf{K}$, $\mathbf{V}$} (VKQ-\i) at (\i, 0) {\t}
    pic foreach \i in {1, 2, 3}
        ["Linear" cell=red, above=of VKQ-\i] (Linear-\i) {shadowed node}
    pic["Scaled Dot-Product Attention" cell=red, above = of Linear-2]
        (Attention) {shadowed node}
    node[above = of Attention, cell=red] (Concat) {Concat}
    node[above = of Concat, cell=red] (Linear) {Linear}
    node[above = of Linear] (MHAtt) {Multi-Head Attention}
    [arrow, ortho/install shortcuts]
    foreach \i in {1, 2, 3}{
        (VKQ-\i) edge coordinate [pos=.2] (@) (Linear-\i)
        (Linear-\i) edge[|*] (Attention)
        foreach \j in {2, 1}{
        [
            edges have transparency group={shadowed node calculation=\j},
            behind path % this edges should be behind the other nodes/pics
        ]
        (@) edge[out=90, in=-90] (Linear-\i-\j)
        [in front of path] % split the following path midway (→ @@)
        (Linear-\i-\j) edge[path only, |*] coordinate (@@) (Attention-\j)
                        edge[-] (@@)                % draw the first half on top
        [behind path] (@@) edge[|*] (Attention-\j) % and the second behind
        }
    }
    foreach \i in {0, 1, 2}{
        [edges have transparency group={shadowed node calculation=\i}]
        (Attention-\i) edge[|*] (Concat)
    }
    (Concat) edge (Linear)
    (Linear) edge (MHAtt);

    % Braced label for H
    \draw[
        arrows={[arc=135]}, arrows={Hooks[left]-Hooks[right]},
        s/.style={shift={(3mm,-3.5mm)}}
    ]
    ([s]Attention-2.east) to[overshoot line to=1mm] coordinate(@) ([s]Attention.east);
    \path node[right=3mm] at (@) {$H$};
\end{tikzpicture}

\begin{tikzpicture}[
    >=LaTeX, % Use default LaTeX arrows
    % Styles 
    node/.style={ % Input or output node
        circle,
        minimum width=2.25em,
        draw,
        fill=gray!10,
        thick
    },
    cell/.style={
        rectangle,
        rounded corners=2mm,
        minimum height=2.5em,
        minimum width=2.5em,
        draw,
        thick
    }, 
    arrow/.style={
        -latex,
        thick
    },
    droparrow/.style={ % Dropout arrows
        arrow,
        dashed
    },
    dropout/.style={ % Dropout nodes
        node,
        dashed
    },
]

    % Input
    \foreach \x in {2}
        \draw node at (0, -\x*1.25 - 0.625) [node] (first_\x) {$x_\x$};
    \draw node at (0, -1*1.25 - 0.625) [dropout] (first_1) {$x_1$};
    \draw node at (0, -5*1.25 + 0.625) [node] (first_n) {$x_n$};
    \path (first_2) -- (first_n) node[pos=0.38, scale=2] {\vdots};

    % Hidden 1
    \foreach \x in {1,3}
        \node at (2.5, -\x*1.25) [node] (second_\x){};
    \draw node at (2.5, -5*1.25) [dropout] (second_m) {};
    \draw node at (2.5, -2*1.25) [dropout] (second_2) {};
    \path (second_3) -- (second_m) node[pos=0.38, scale=2] {\vdots};

    % Hidden 2
    \foreach \x in {2}
        \node at (5, -\x*1.25) [node] (third_\x){};
    \draw node at (5, -1*1.25) [dropout] (third_1) {};
    \draw node at (5, -3*1.25) [dropout] (third_3) {};
    \draw node at (5, -5*1.25) [node] (third_m) {};
    \path (third_3) -- (third_m) node[pos=0.38, scale=2] {\vdots};

    % Output
    \foreach \x in {1,...,2}
        \node at (7.5, -\x*1.25 - 0.625) [node] (fourth_\x){$\hat{y}_\x$};
    \draw node at (7.5, -5*1.25 + 0.625) [node] (fourth_k) {$\hat{y}_m$};
    \path (fourth_2) -- (fourth_k) node[pos=0.38, scale=2] {\vdots};

    % Input -> Hidden
    \foreach \i in {2}
        \foreach \j in {1,3}
            \draw [arrow] (first_\i) to (second_\j);
    \foreach \i in {1,3}
        \draw [arrow] (first_n) to (second_\i);

    % Hidden -> Hidden
    \foreach \i in {1,3}
        \foreach \j in {2}
            \draw [arrow] (second_\i) to (third_\j);
    \foreach \i in {1,3}
        \draw [arrow] (second_\i) to (third_m);

    % Hidden -> Output
    \foreach \i in {2}
        \foreach \j in {1,...,2}
            \draw [arrow] (third_\i) to (fourth_\j);
    \foreach \i in {1,...,2}
        \draw [arrow] (third_m) to (fourth_\i);
    \draw [arrow] (third_m) to (fourth_k);
    \draw [arrow] (third_2) to (fourth_k);

    % Layer Labels
    \node[above=0.25cm of first_1] (xlabel) {$\mathbf{x}$};
    \node[above=0.25cm of second_1] (h1label) {$\mathbf{h}^{(1)}$};
    \node[above=0.25cm of third_1] (h2label) {$\mathbf{h}^{(2)}$};
    \node[above=0.25cm of fourth_1] (ylabel) {$\hat{\mathbf{y}}$};

    \node[cell, dashed, fit=(first_1) (first_n)] (xbox) {};
    \node[cell, dashed, fit=(second_1) (second_m)] (xbox) {};
    \node[cell, dashed, fit=(third_1) (third_m)] (xbox) {};
    \node[cell, dashed, fit=(fourth_1) (fourth_k)] (xbox) {};
\end{tikzpicture}

\begin{tikzpicture}[
    >=LaTeX, % Use default LaTeX arrows
    very thick,
    arrow/.style={
        -latex,
        very thick,
        rounded corners=0.2cm
    },
    block/.style={
        rectangle,
        fill=gray!10,
        rounded corners=3mm,
        draw,
        very thick
    },
    layer/.style={
        rectangle,
        fill=white!10,
        rounded corners=1mm,
        inner xsep=0em,
        inner ysep=0.25em,
        minimum height=1.4em,
        align=center,
        text width=2.5cm,
        draw,
        very thick
    },
    input/.style={ % Input or output node
        circle,
        minimum width=2.25em,
        draw,
        fill=gray!10,
        thick
    },
    do path picture/.style={%
        path picture={%
          \pgfpointdiff{\pgfpointanchor{path picture bounding box}{south west}}%
            {\pgfpointanchor{path picture bounding box}{north east}}%
          \pgfgetlastxy\x\y%
          \tikzset{x=\x/2,y=\y/2}%
          #1
        }
    },
    sin wave/.style={do path picture={    
        \draw [line cap=round] (-3/4,0)
        sin (-3/8,1/2) cos (0,0) sin (3/8,-1/2) cos (3/4,0);
        }
    }
]

    \node[input] (iemb) at (1.25,-0.45) {$\mathbf{x}$};
    \node[input] (oemb) at (5.25,-0.45) {$\mathbf{y}$};

    % Sums
    \node[circle, draw, minimum size=0.25em, inner sep=0pt, above=1em of iemb] (sum1) {$\mathbf{+}$};
    \node[circle, draw, minimum size=0.25em, inner sep=0pt, above=1em of oemb] (sum2) {$\mathbf{+}$};
    % Positional Encoding
    \node [circle, draw, sin wave, minimum size=2em, left=0.8em of sum1] (pe1) {};
    \node [circle, draw, sin wave, minimum size=2em, right=0.8em of sum2] (pe2) {};

    % Encoder, 1st layer
    \node[layer] (add1) at (1.25,3.43) {Add \& Norm};
    \node[layer] (attn1) at (1.25,2.58) {Multi-Head \vspace{-0.05cm} \linebreak Attention};
    \draw[] (attn1) -- (add1);
    % Encoder 2nd sub-layer
    \node[layer] (add4) at (1.25,5.98) {Add \& Norm};
    \node[layer] (ff1) at (1.25,5.13) {Feed \vspace{-0.05cm} \linebreak Forward};
    \draw[] (ff1) -- (add4);

    % Decoder 1st sub-layer
    \node[layer] (add3) at (5.25,3.83) {Add \& Norm};
    \node[layer] (attn3) at (5.25,2.78) {Masked \vspace{-0.05cm} \linebreak Multi-Head \vspace{-0.05cm} \linebreak Attention};
    \draw[] (attn3) -- (add3);
    % Decoder, 2nd sub-layer
    \node[layer] (add2) at (5.25,6.38) {Add \& Norm};
    \node[layer] (attn2) at (5.25,5.53) {Multi-Head \vspace{-0.05cm} \linebreak Attention};
    \draw[] (attn2) -- (add2);
    % Decoder 3rd sub-layer
    \node[layer] (add5) at (5.25,8.93) {Add \& Norm};
    \node[layer] (ff2) at (5.25,8.08) {Feed \vspace{-0.05cm} \linebreak Forward};
    \draw[] (ff2) -- (add5);

    \coordinate (d1) at ($(attn3.south east) + (0.75,-0.7)$);
    \coordinate (d2) at ($(add5.north west) + (-0.15,0.05)$);
    \coordinate (e1) at ($(attn1.south east) + (0.15,-0.7)$);
    \coordinate (e2) at ($(add4.north west) + (-0.75,0.05)$);
    \begin{scope}[on background layer]
        \node[block, fit=(d1) (d2)] (decoder) {};
        \node[block, fit=(e1) (e2)] (encoder) {};
    \end{scope}

    % Classifier
    \node[layer, above=1.5em of add5] (linear) {Linear};
    \node[layer, above=1em of linear] (softmax) {Softmax};
    \node[input, above=1em of softmax] (probs) {$\hat{\mathbf{y}}$};

    \draw[arrow] (add1) -- (ff1);
    \draw[arrow] (add2) -- (ff2);
    \draw[arrow] (add5) -- (linear);
    \draw[arrow] (linear) -- (softmax);
    \draw[arrow] (iemb) -- (sum1);
    \draw[arrow] (sum1) -- (attn1);
    \draw[arrow] (oemb) -- (sum2);
    \draw[arrow] (sum2) -- (attn3);
    \draw[] (sum1) -- (pe1);
    \draw[] (sum2) -- (pe2);

    \draw[arrow] (ff1.south)++(0, -0.6) -| ($(add4.west) + (-0.6,-0.5)$) |- (add4.west);
    \draw[arrow] (attn1.south)++(0, -0.6) -| ($(add1.west) + (-0.6,-0.5)$) |- (add1.west);

    \draw[arrow] (attn3.south)++(0, -0.6) -| ($(add3.east) + (0.6,-0.5)$) |- (add3.east);
    \draw[arrow] (attn2.south)++(0, -0.6) -| ($(add2.east) + (0.6,-0.5)$) |- (add2.east);
