          \draw (\a:\circRad + 2mm) -- (\a:\circRad);
        }
      \foreach \itm [count=\i, evaluate={\a=30-\i*15;}] in
        {efficiency, speed, compactness} {
          \node[challenge] at (\a:\circRad + 2mm) [rotate=\a, anchor=west] {\itm};
